<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Http\ApiError;final class UserAvatar{public const MAX_BYTES=524288;public static function version(string$user):?string{try{return DB::one('SELECT avatar_version FROM user_profiles WHERE user_id=?',[$user])['avatar_version']??null;}catch(\PDOException$error){if((int)($error->errorInfo[1]??0)!==1054)throw$error;return null;}}public static function save(string$user,string$jpeg):string{$jpeg=self::withoutMetadata($jpeg);$version=DB::id();try{DB::run('INSERT INTO user_profiles(user_id,avatar_jpeg,avatar_version) VALUES(?,?,?) AS incoming
